  const miId = MEITI.obtenerUsuarioActual();

  const [carrito, setCarrito] = useState([]);
  const [variantes, setVariantes] = useState([]);
  const [precios, setPrecios] = useState([]);
  const [zonas, setZonas] = useState([]);

  const [form, setForm] = useState({ zona_id: '', direccion: '', notas: '', metodo_pago: 'tarjeta' });
  const [cargando, setCargando] = useState(true);
  const [procesando, setProcesando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const [resCart, resVar, resPrecios, resZonas] = await Promise.all([
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ur_carrito')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/pagos-conectados/${eco}/precios`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_zonas_envio')}?ecosistema=${eco}`)
      ]);

      if (resCart.ok) setCarrito(resCart.registros || []);
      if (resVar.ok) setVariantes(resVar.registros || []);
      if (resPrecios.ok) setPrecios(resPrecios.registros || []);
      if (resZonas.ok) {
        const z = resZonas.registros || [];
        setZonas(z);
        if (z.length > 0) setForm(f => ({ ...f, zona_id: z[0].id }));
      }
      setCargando(false);
    };
    cargar();
  }, []);

  const subtotal = carrito.reduce((acc, item) => {
    const v = variantes.find(x => x.id === item.variante_id);
    if (!v) return acc;
    const p = precios.find(x => x.item_id === v.producto_id);
    return acc + (p ? (p.monto_centavos / 100) : 0) * item.cantidad;
  }, 0);

  const zonaSel = zonas.find(z => z.id === form.zona_id);
  const costoEnvio = zonaSel ? Number(zonaSel.costo) : 0;
  const total = subtotal + costoEnvio;

  const procesarPedidoManual = async () => {
    const pedidoId = 'ped_' + Date.now();
    const mutaciones = [
      {
        url: `/api/boveda/${MEITI.obtenerTabla('ur_pedidos')}?ecosistema=${eco}`,
        opciones: {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: pedidoId,
            usuario_id: miId,
            estado: 'pendiente',
            total: total,
            metodo_pago: form.metodo_pago,
            zona_envio_id: form.zona_id,
            direccion_envio: form.direccion.trim(),
            notas: form.notas.trim(),
            fecha_registro: new Date().toISOString()
          })
        }
      },
      ...carrito.map(item => {
        const v = variantes.find(x => x.id === item.variante_id);
        const p = precios.find(x => x.item_id === v?.producto_id);
        return {
          url: `/api/boveda/${MEITI.obtenerTabla('ur_pedido_items')}?ecosistema=${eco}`,
          opciones: {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              id: 'pitem_' + Date.now() + Math.random().toString(36).substring(7),
              pedido_id: pedidoId,
              variante_id: item.variante_id,
              cantidad: item.cantidad,
              precio_unitario: p ? (p.monto_centavos / 100) : 0
            })
          }
        };
      }),
      ...carrito.map(item => ({
        url: `/api/boveda/${MEITI.obtenerTabla('ur_carrito')}?ecosistema=${eco}&id=${item.id}`,
        opciones: { method: 'DELETE' }
      }))
    ];

    await MEITI.mutarVarias(mutaciones, {
      alLograr: () => {
        setExito('¡Pedido registrado con éxito!');
        setProcesando(false);
        setTimeout(() => MEITI.irAPagina('mis_pedidos'), 3000);
      },
      alFallar: (err) => {
        setError(err || 'Error al procesar el pedido');
        setProcesando(false);
      }
    });
  };

  const confirmar = async () => {
    if (!form.direccion.trim()) return setError('Ingresa una dirección de entrega.');
    if (!form.zona_id) return setError('Selecciona una zona de envío.');

    setProcesando(true);
    setError(null);

    if (form.metodo_pago === 'tarjeta') {
      const v = variantes.find(x => x.id === carrito[0].variante_id);
      const res = await MEITI.fetchMutante(`/api/pagos-conectados/${eco}/comprar`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          item_id: v.producto_id,
          usuario_id: miId,
          url_exito: window.location.origin,
          url_cancelado: window.location.href
        })
      });

      if (!res.ok) {
        setError(res.error || 'El administrador aún no configuró los pagos online. Por favor, elige Transferencia o Efectivo.');
        setProcesando(false);
        return;
      }
      MEITI.abrirEnlaceExterno(res.data.url);
    } else {
      await procesarPedidoManual();
    }
  };

  if (cargando) return <div className="p-12 text-center"><Iconos.LoaderCircle size={48} className="animate-spin mx-auto" color={tema.colorPrimario} /></div>;
  if (carrito.length === 0 && !exito) return <UI.EstadoVacio icono="fa-basket-shopping" mensaje="No hay nada que pagar." />;

  if (exito) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] gap-6 text-center">
        <Animacion.motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="w-24 h-24 rounded-full flex items-center justify-center" style={{ background: tema.colorSecundario, color: '#fff' }}>
          <Iconos.CheckCheck size={48} />
        </Animacion.motion.div>
        <h2 className="font-serif text-4xl" style={{ color: tema.texto }}>{exito}</h2>
        <p className="opacity-70" style={{ color: tema.texto }}>Te redirigiremos a tus pedidos en breve...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-24">
      <h1 className="font-serif text-4xl tracking-tight" style={{ color: tema.texto }}>Finalizar Pedido</h1>
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="flex flex-col gap-6">
          <UI.Tarjeta className="p-6 rounded-3xl flex flex-col gap-4">
            <h3 className="font-serif text-2xl font-bold" style={{ color: tema.texto }}>1. Entrega</h3>
            <div className="flex flex-col gap-4">
              <div className="flex-1">
                <UI.Campo 
                  etiqueta="Zona de Envío"
                  tipo="select"
                  valor={form.zona_id}
                  onChange={e => setForm({...form, zona_id: e.target.value})}
                  opciones={zonas.map(z => ({ value: z.id, label: `${z.nombre} (+$${z.costo})` }))}
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta="Dirección Completa"
                  tipo="text"
                  valor={form.direccion}
                  onChange={e => setForm({...form, direccion: e.target.value})}
                  placeholder="Calle, Número, Piso, Depto, Ciudad"
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta="Notas para el envío (opcional)"
                  tipo="textarea"
                  valor={form.notas}
                  onChange={e => setForm({...form, notas: e.target.value})}
                  placeholder="Ej: Tocar timbre fuerte, dejar en portería..."
                />
              </div>
            </div>
          </UI.Tarjeta>

          <UI.Tarjeta className="p-6 rounded-3xl flex flex-col gap-4">
            <h3 className="font-serif text-2xl font-bold" style={{ color: tema.texto }}>2. Pago</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              {[ 
                { id: 'tarjeta', label: 'Tarjeta (Online)', icon: <Iconos.CreditCard size={24} /> },
                { id: 'transferencia', label: 'Transferencia', icon: <Iconos.Landmark size={24} /> },
                { id: 'efectivo', label: 'Contra Entrega', icon: <Iconos.Banknote size={24} /> }
              ].map(m => (
                <button
                  key={m.id}
                  onClick={() => setForm({...form, metodo_pago: m.id})}
                  className="p-4 rounded-2xl flex flex-col items-center gap-3 transition-all border-2"
                  style={{ 
                    background: form.metodo_pago === m.id ? tema.colorPrimario : tema.superficie,
                    color: form.metodo_pago === m.id ? '#fff' : tema.texto,
                    borderColor: form.metodo_pago === m.id ? tema.colorPrimario : tema.texto + '22'
                  }}
                >
                  {m.icon}
                  <span className="font-bold text-sm text-center">{m.label}</span>
                </button>
              ))}
            </div>
          </UI.Tarjeta>
        </div>

        <div className="flex flex-col gap-6">
          <UI.Tarjeta className="p-6 rounded-3xl flex flex-col gap-4">
            <h3 className="font-serif text-2xl font-bold" style={{ color: tema.texto }}>Resumen Final</h3>
            <div className="flex flex-col gap-3 opacity-80" style={{ color: tema.texto }}>
              <div className="flex justify-between"><span>Subtotal</span><span className="font-mono">${subtotal.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>Envío ({zonaSel?.nombre || '...'})</span><span className="font-mono">${costoEnvio.toFixed(2)}</span></div>
            </div>
            <div className="h-px w-full opacity-10 my-2" style={{ background: tema.texto }} />
            <div className="flex justify-between items-center text-3xl font-black" style={{ color: tema.texto }}>
              <span>Total</span>
              <span className="font-mono">${total.toFixed(2)}</span>
            </div>
          </UI.Tarjeta>

          <button 
            onClick={confirmar}
            disabled={procesando}
            className="w-full py-5 rounded-2xl font-bold text-xl flex items-center justify-center gap-3 transition-transform active:scale-95 shadow-xl"
            style={{ background: tema.colorSecundario, color: '#fff', opacity: procesando ? 0.7 : 1 }}
          >
            {procesando ? <Iconos.LoaderCircle size={24} className="animate-spin" /> : <Iconos.CheckCircle size={24} />}
            {procesando ? 'Procesando...' : 'Confirmar y Pagar'}
          </button>
        </div>
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [pedidos, setPedidos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ur_pedidos')}?ecosistema=${eco}`);
      if (res.ok) {
        setPedidos(res.registros.sort((a, b) => new Date(b.fecha_registro) - new Date(a.fecha_registro)));
      } else {
        setError(res.error || 'Error al cargar pedidos');
      }
      setCargando(false);
    };
    cargar();
  }, []);

  const columnas = [
    { clave: 'id', etiqueta: 'Nº Pedido', render: f => <span className="font-mono text-xs opacity-70">{f.id ? f.id.split('_')[1] : ''}</span> },
    { clave: 'fecha_registro', etiqueta: 'Fecha', tipo: 'fecha' },
    { clave: 'total', etiqueta: 'Total', tipo: 'moneda' },
    { clave: 'metodo_pago', etiqueta: 'Pago', render: f => <span className="capitalize">{f.metodo_pago}</span> },
    { clave: 'estado', etiqueta: 'Estado', render: f => (
      <UI.Chip tono={f.estado === 'entregado' ? 'exito' : f.estado === 'cancelado' ? 'peligro' : 'alerta'}>
        {f.estado ? f.estado.toUpperCase() : ''}
      </UI.Chip>
    )}
  ];

  return (
    <div className="flex flex-col gap-8">
      <h1 className="font-serif text-4xl tracking-tight" style={{ color: tema.texto }}>Mis Pedidos</h1>
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <UI.Tarjeta className="p-6 rounded-3xl">
        {cargando ? (
          <div className="p-8 text-center"><i className="fa-solid fa-spinner fa-spin text-3xl" style={{ color: tema.colorPrimario }}></i></div>
        ) : pedidos.length === 0 ? (
          <UI.EstadoVacio icono="fa-box-open" mensaje="Todavía no has realizado ninguna compra." />
        ) : (
          <UI.TablaDatos 
            columnas={columnas} 
            datos={pedidos} 
            claveId="id"
            advertirAccionIncompleta={false}
            accionesExtra={[
              { etiqueta: 'Ver Detalle', icono: 'fa-eye', tono: 'neutro', onClick: () => setError('Detalle en construcción') }
            ]}
          />
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [pedidos, setPedidos] = useState([]);
  const [items, setItems] = useState([]);
  const [variantes, setVariantes] = useState([]);
  const [productos, setProductos] = useState([]);
  const [estados, setEstados] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [filtroEstado, setFiltroEstado] = useState('');
  const [pedidoActivo, setPedidoActivo] = useState(null);
  const [nuevoEstado, setNuevoEstado] = useState('');
  const [guardando, setGuardando] = useState(false);

  const cargarDatos = async () => {
    setCargando(true);
    try {
      const [resPed, resItm, resVar, resProd, resEst] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_pedidos')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_pedido_items')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_productos')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_estados_pedido')}?ecosistema=${eco}`)
      ]);

      if (resPed.ok) setPedidos(resPed.registros.sort((a,b) => new Date(b.fecha_registro) - new Date(a.fecha_registro)));
      if (resItm.ok) setItems(resItm.registros);
      if (resVar.ok) setVariantes(resVar.registros);
      if (resProd.ok) setProductos(resProd.registros);
      if (resEst.ok) setEstados(resEst.registros);
    } catch (err) {
      setError(MEITI.t('err_load_orders', null, 'Error al cargar los pedidos.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    if (soyAdmin) cargarDatos();
  }, [soyAdmin]);

  if (!soyAdmin) return <UI.Aviso tono="peligro" mensaje={MEITI.t('admin_only', null, 'Acceso denegado. Solo administradores.')} />;

  const actualizarEstado = async () => {
    if (!pedidoActivo || !nuevoEstado) return;
    setGuardando(true);
    const payload = { ...pedidoActivo, estado: nuevoEstado };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ur_pedidos')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setPedidoActivo(null);
        setNuevoEstado('');
        cargarDatos();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_update_order', null, 'Error al actualizar el pedido.'));
        setGuardando(false);
      }
    });
  };

  const pedidosFiltrados = filtroEstado ? pedidos.filter(p => p.estado === filtroEstado) : pedidos;

  const columnas = [
    { clave: 'id', etiqueta: MEITI.t('col_id', null, 'ID'), render: f => f.id.split('_')[1] || f.id },
    { clave: 'fecha_registro', etiqueta: MEITI.t('col_date', null, 'Fecha'), tipo: 'fecha' },
    { clave: 'total', etiqueta: MEITI.t('col_total', null, 'Total'), tipo: 'moneda' },
    { clave: 'metodo_pago', etiqueta: MEITI.t('col_payment', null, 'Pago'), render: f => <span className="uppercase text-xs font-bold">{f.metodo_pago}</span> },
    { clave: 'estado', etiqueta: MEITI.t('col_status', null, 'Estado'), render: f => {
        const est = estados.find(e => e.nombre === f.estado);
        return <UI.Chip tono={est ? est.color : 'neutro'}>{f.estado || '---'}</UI.Chip>;
    }}
  ];

  const accionesExtra = [
    {
      etiqueta: MEITI.t('btn_view_details', null, 'Ver Detalles'),
      icono: 'fa-eye',
      tono: 'primario',
      onClick: (f) => { setPedidoActivo(f); setNuevoEstado(f.estado || ''); }
    }
  ];

  return (
    <div className="flex flex-col gap-6 flex-1 min-h-0">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      {!pedidoActivo ? (
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} className="flex flex-col flex-1 min-h-0">
          <UI.Tarjeta className="flex flex-col gap-4 flex-1 min-h-0">
            <div className="flex justify-between items-center flex-wrap gap-4">
              <div className="flex items-center gap-3">
                <Iconos.Package size={24} color={tema.colorPrimario} />
                <h2 className="text-xl font-bold" style={{ color: tema.texto }}>{MEITI.t('title_orders', null, 'Gestión de Pedidos')}</h2>
              </div>
              <div className="w-full md:w-64">
                <UI.Desplegable 
                  valor={filtroEstado} 
                  onCambio={e => setFiltroEstado(e.target.value)} 
                  opciones={[{value: '', label: MEITI.t('all_statuses', null, 'Todos los estados')}, ...estados.map(e => ({value: e.nombre, label: e.nombre}))]} 
                />
              </div>
            </div>

            {cargando ? (
              <div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div>
            ) : pedidosFiltrados.length === 0 ? (
              <UI.EstadoVacio icono="fa-box-open" mensaje={MEITI.t('no_orders', null, 'No hay pedidos para mostrar.')} />
            ) : (
              <div className="flex-1 overflow-y-auto min-h-0">
                <UI.TablaDatos 
                  columnas={columnas} 
                  datos={pedidosFiltrados} 
                  claveId="id" 
                  accionesExtra={accionesExtra} 
                  advertirAccionIncompleta={false} 
                />
              </div>
            )}
          </UI.Tarjeta>
        </Animacion.motion.div>
      ) : (
        <Animacion.motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.2 }} className="flex flex-col flex-1 min-h-0">
          <UI.Tarjeta className="flex flex-col gap-6 flex-1 min-h-0">
            <div className="flex items-center justify-between border-b pb-4" style={{ borderColor: tema.texto + '22' }}>
              <div className="flex items-center gap-3">
                <button onClick={() => setPedidoActivo(null)} className="p-2 rounded-full hover:bg-black/5 transition-colors">
                  <Iconos.ArrowLeft size={20} color={tema.texto} />
                </button>
                <h3 className="text-lg font-bold" style={{ color: tema.texto }}>
                  {MEITI.t('order_details_title', { id: pedidoActivo.id.split('_')[1] || pedidoActivo.id }, 'Pedido #{id}')}
                </h3>
              </div>
              <UI.Chip tono="neutro">{new Date(pedidoActivo.fecha_registro).toLocaleString()}</UI.Chip>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-0">
              <div className="flex flex-col gap-4">
                <UI.Etiqueta>{MEITI.t('lbl_customer_info', null, 'Información de Envío')}</UI.Etiqueta>
                <div className="p-4 rounded-xl" style={{ background: tema.superficie }}>
                  <p className="text-sm opacity-80 mb-1" style={{ color: tema.texto }}>{MEITI.t('lbl_address', null, 'Dirección:')}</p>
                  <p className="font-medium mb-3" style={{ color: tema.texto }}>{pedidoActivo.direccion_envio || '---'}</p>

                  <p className="text-sm opacity-80 mb-1" style={{ color: tema.texto }}>{MEITI.t('lbl_notes', null, 'Notas del cliente:')}</p>
                  <p className="font-medium italic" style={{ color: tema.texto }}>{pedidoActivo.notas || MEITI.t('no_notes', null, 'Sin notas')}</p>
                </div>

                <UI.Etiqueta>{MEITI.t('lbl_update_status', null, 'Actualizar Estado')}</UI.Etiqueta>
                <div className="flex gap-2 items-end">
                  <div className="flex-1">
                    <UI.Campo 
                      tipo="select" 
                      valor={nuevoEstado} 
                      onChange={e => setNuevoEstado(e.target.value)} 
                      opciones={estados.map(e => ({value: e.nombre, label: e.nombre}))} 
                    />
                  </div>
                  <UI.Boton onClick={actualizarEstado} variante="primario" disabled={guardando || nuevoEstado === pedidoActivo.estado}>
                    {guardando ? <Iconos.LoaderCircle className="animate-spin" size={18} /> : <Iconos.Save size={18} />}
                  </UI.Boton>
                </div>
              </div>

              <div className="flex flex-col gap-4 flex-1 min-h-0">
                <UI.Etiqueta>{MEITI.t('lbl_order_items', null, 'Artículos del Pedido')}</UI.Etiqueta>
                <div className="flex flex-col gap-2 flex-1 overflow-y-auto pr-2 min-h-0">
                  {items.filter(i => i.pedido_id === pedidoActivo.id).map(item => {
                    const variante = variantes.find(v => v.id === item.variante_id) || {};
                    const producto = productos.find(p => p.id === variante.producto_id) || {};
                    return (
                      <div key={item.id} className="flex items-center gap-3 p-3 rounded-lg border" style={{ borderColor: tema.texto + '11', background: tema.fondo }}>
                        {producto.imagen_principal ? (
                          <img src={producto.imagen_principal} alt={producto.nombre} className="w-12 h-12 rounded-md object-cover" />
                        ) : (
                          <div className="w-12 h-12 rounded-md flex items-center justify-center bg-black/5"><Iconos.Image size={20} color={tema.texto} opacity={0.3} /></div>
                        )}
                        <div className="flex-1 min-w-0">
                          <p className="font-bold text-sm truncate" style={{ color: tema.texto }}>{producto.nombre || MEITI.t('unknown_product', null, 'Producto Desconocido')}</p>
                          <p className="text-xs opacity-70" style={{ color: tema.texto }}>SKU: {variante.sku || '---'}</p>
                        </div>
                        <div className="text-right">
                          <p className="font-bold" style={{ color: tema.texto }}>{item.cantidad}x</p>
                          <p className="text-sm" style={{ color: tema.colorSecundario }}>${(item.precio_unitario * item.cantidad).toFixed(2)}</p>
                        </div>
                      </div>
                    );
                  })}
                </div>
                <div className="mt-auto pt-4 border-t flex justify-between items-center" style={{ borderColor: tema.texto + '22' }}>
                  <span className="font-bold text-lg" style={{ color: tema.texto }}>{MEITI.t('lbl_total', null, 'Total Pagado:')}</span>
                  <span className="font-black text-2xl" style={{ color: tema.colorPrimario }}>${pedidoActivo.total.toFixed(2)}</span>
                </div>
              </div>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [estados, setEstados] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const vacio = { id: '', nombre: '', color: 'neutro', orden: '0' };
  const [form, setForm] = useState(vacio);
  const [guardando, setGuardando] = useState(false);

  const cargarDatos = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatos(`http://localhost:4001/api/boveda/${MEITI.obtenerTabla('ur_estados_pedido')}?ecosistema=${eco}`);
    if (res.ok) {
      setEstados(res.registros.sort((a, b) => (Number(a.orden) || 0) - (Number(b.orden) || 0)));
    } else {
      setError(MEITI.t('err_load_statuses', null, 'Error al cargar los estados de pedido.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    if (soyAdmin) cargarDatos();
  }, [soyAdmin]);

  if (!soyAdmin) {
    return <UI.Aviso tono="alerta" mensaje={MEITI.t('admin_only', null, 'Esta sección es solo para administradores.')} />;
  }

  const guardar = async (e) => {
    e.preventDefault();
    if (!form.nombre.trim()) return setError(MEITI.t('err_name_req', null, 'El nombre del estado es obligatorio.'));
    setGuardando(true);
    setError(null);
    setExito(null);

    const payload = {
      id: form.id || 'est_' + Date.now(),
      nombre: form.nombre.trim(),
      color: form.color,
      orden: Number(form.orden) || 0
    };

    await MEITI.mutar(`http://localhost:4001/api/boveda/${MEITI.obtenerTabla('ur_estados_pedido')}?ecosistema=${eco}`, {
      method: form.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('msg_status_saved', null, 'Estado guardado correctamente.'));
        setForm(vacio);
        cargarDatos();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save_status', null, 'Error al guardar el estado.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('q_delete_status', null, '¿Borrar este estado?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`http://localhost:4001/api/boveda/${MEITI.obtenerTabla('ur_estados_pedido')}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: cargarDatos,
      alFallar: setError
    });
  };

  const columnas = [
    { clave: 'orden', etiqueta: MEITI.t('col_order', null, 'Orden'), tipo: 'numero' },
    { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') },
    { clave: 'color', etiqueta: MEITI.t('col_color', null, 'Color'), render: f => <UI.Chip tono={f.color}>{MEITI.t(`color_${f.color}`, null, f.color)}</UI.Chip> }
  ];

  const opcionesColor = [
    { value: 'neutro', label: MEITI.t('color_neutro', null, 'Gris (Neutro)') },
    { value: 'primario', label: MEITI.t('color_primario', null, 'Primario') },
    { value: 'secundario', label: MEITI.t('color_secundario', null, 'Secundario') },
    { value: 'exito', label: MEITI.t('color_exito', null, 'Verde (Éxito)') },
    { value: 'alerta', label: MEITI.t('color_alerta', null, 'Amarillo (Alerta)') },
    { value: 'peligro', label: MEITI.t('color_peligro', null, 'Rojo (Peligro)') }
  ];

  return (
    <UI.Tarjeta className="flex flex-col gap-6 mt-6 flex-1 min-h-0">
      <div className="flex items-center gap-3">
        <i className="fa-solid fa-tags text-xl" style={{ color: tema.colorSecundario }}></i>
        <h3 className="text-lg font-bold" style={{ color: tema.texto }}>{MEITI.t('title_manage_statuses', null, 'Configurar Estados de Pedido')}</h3>
      </div>

      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

      <form onSubmit={guardar} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
        <div className="flex-1">
          <UI.Campo etiqueta={MEITI.t('lbl_name', null, 'Nombre')} tipo="text" valor={form.nombre} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_status_name', null, 'Ej: En Preparación')} />
        </div>
        <div className="flex-1">
          <UI.Campo etiqueta={MEITI.t('lbl_color', null, 'Color')} tipo="select" valor={form.color} onChange={e => setForm({...form, color: e.target.value})} opciones={opcionesColor} />
        </div>
        <div className="flex-1">
          <UI.Campo etiqueta={MEITI.t('lbl_order', null, 'Orden')} tipo="number" valor={form.orden} onChange={e => setForm({...form, orden: e.target.value})} />
        </div>
        <div className="flex-1">
          <UI.Boton tipo="submit" variante="primario" disabled={guardando}>{form.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_add', null, 'Agregar')}</UI.Boton>
        </div>
      </form>

      {cargando ? (
        <UI.Etiqueta>{MEITI.t('loading', null, 'Cargando...')}</UI.Etiqueta>
      ) : estados.length === 0 ? (
        <UI.EstadoVacio icono="fa-tags" mensaje={MEITI.t('no_statuses', null, 'No hay estados configurados. Agrega el primero arriba.')} />
      ) : (
        <div className="flex-1 overflow-y-auto min-h-0">
          <UI.TablaDatos 
            columnas={columnas} 
            datos={estados} 
            claveId="id" 
            onEditar={f => { setForm({ id: f.id, nombre: f.nombre, color: f.color || 'neutro', orden: String(f.orden||0) }); setError(null); setExito(null); }} 
            onBorrar={f => borrar(f.id)} 
          />
        </div>
      )}
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [alertas, setAlertas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const cargarDatos = async () => {
    setCargando(true);
    try {
      const [resVar, resProd, resTal, resCol] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_productos')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_talles')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_colores')}?ecosistema=${eco}`)
      ]);

      if (resVar.ok && resProd.ok) {
        const variantes = resVar.registros || [];
        const productos = resProd.registros || [];
        const talles = resTal.registros || [];
        const colores = resCol.registros || [];

        const criticos = variantes
          .filter(v => Number(v.stock) <= 5)
          .map(v => {
            const prod = productos.find(p => p.id === v.producto_id) || {};
            const talle = talles.find(t => t.id === v.talle_id) || {};
            const color = colores.find(c => c.id === v.color_id) || {};
            return {
              ...v,
              producto_nombre: prod.nombre || MEITI.t('unknown_prod', null, 'Producto Desconocido'),
              talle_nombre: talle.nombre || '---',
              color_nombre: color.nombre || '---',
              color_hex: color.hex || '#ccc',
              imagen: prod.imagen_principal
            };
          })
          .sort((a, b) => Number(a.stock) - Number(b.stock));

        setAlertas(criticos);
      } else {
        setError(MEITI.t('err_load_alerts', null, 'No se pudieron cargar las alertas de stock.'));
      }
    } catch (err) {
      setError(MEITI.t('err_general_alerts', null, 'Error al procesar las alertas.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    if (soyAdmin) cargarDatos();

    const interval = setInterval(cargarDatos, 30000);
    return () => clearInterval(interval);
  }, [soyAdmin]);

  if (!soyAdmin) return null;

  if (cargando && alertas.length === 0) {
    return (
      <UI.Tarjeta>
        <div className="p-6 text-center flex flex-col items-center gap-3">
          <Iconos.LoaderCircle className="animate-spin" size={32} color={tema.colorPrimario} />
          <span style={{ color: tema.texto }}>{MEITI.t('loading_alerts', null, 'Revisando existencias...')}</span>
        </div>
      </UI.Tarjeta>
    );
  }

  if (alertas.length === 0 && !error) return null;

  return (
    <Animacion.motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
      <UI.Tarjeta className="flex flex-col gap-4" style={{ border: `1px solid #ef444455` }}>
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-full bg-red-100 text-red-600">
            <Iconos.TriangleAlert size={24} />
          </div>
          <div>
            <h2 className="text-lg font-bold text-red-600">{MEITI.t('title_stock_alerts', null, 'Alertas de Stock Crítico')}</h2>
            <p className="text-sm opacity-80" style={{ color: tema.texto }}>{MEITI.t('desc_stock_alerts', null, 'Artículos con 5 o menos unidades disponibles.')}</p>
          </div>
        </div>

        <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {alertas.map(a => (
            <div key={a.id} className="flex items-center gap-3 p-3 rounded-xl border" style={{ borderColor: tema.texto + '22', background: tema.fondo }}>
              {a.imagen ? (
                <img src={a.imagen} alt={a.producto_nombre} className="w-12 h-12 rounded-lg object-cover flex-shrink-0" />
              ) : (
                <div className="w-12 h-12 rounded-lg flex items-center justify-center bg-black/5 flex-shrink-0">
                  <Iconos.Package size={20} color={tema.texto} opacity={0.3} />
                </div>
              )}
              <div className="flex-1 min-w-0">
                <p className="font-bold text-sm truncate" style={{ color: tema.texto }}>{a.producto_nombre}</p>
                <div className="flex items-center gap-2 text-xs mt-1">
                  <span className="px-2 py-0.5 rounded-md bg-black/5" style={{ color: tema.texto }}>{a.talle_nombre}</span>
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-black/5">
                    <div className="w-2 h-2 rounded-full" style={{ background: a.color_hex }}></div>
                    <span style={{ color: tema.texto }}>{a.color_nombre}</span>
                  </div>
                </div>
              </div>
              <div className="flex flex-col items-center justify-center px-3 py-1 rounded-lg" style={{ background: Number(a.stock) === 0 ? '#ef444422' : '#f59e0b22' }}>
                <span className="text-xs font-bold uppercase" style={{ color: Number(a.stock) === 0 ? '#ef4444' : '#f59e0b' }}>{MEITI.t('lbl_stock', null, 'Stock')}</span>
                <span className="text-xl font-black" style={{ color: Number(a.stock) === 0 ? '#ef4444' : '#f59e0b' }}>{a.stock}</span>
              </div>
            </div>
          ))}
        </div>
      </UI.Tarjeta>
    </Animacion.motion.div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [variantes, setVariantes] = useState([]);
  const [productos, setProductos] = useState([]);
  const [talles, setTalles] = useState([]);
  const [colores, setColores] = useState([]);
  const [categorias, setCategorias] = useState([]);

  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);
  const [guardando, setGuardando] = useState(false);

  const [filtroProd, setFiltroProd] = useState('');

  const vacio = { id: '', producto_id: '', talle_id: '', color_id: '', stock: '0', sku: '' };
  const [form, setForm] = useState(vacio);
  const [editando, setEditando] = useState(false);

  const cargarDatos = async () => {
    setCargando(true);
    try {
      const [resVar, resProd, resTal, resCol, resCat] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_productos')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_talles')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_colores')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ur_categorias')}?ecosistema=${eco}`)
      ]);

      if (resVar.ok) setVariantes(resVar.registros || []);
      if (resProd.ok) setProductos(resProd.registros || []);
      if (resTal.ok) setTalles(resTal.registros.sort((a,b) => (a.orden||0)-(b.orden||0)) || []);
      if (resCol.ok) setColores(resCol.registros.sort((a,b) => (a.orden||0)-(b.orden||0)) || []);
      if (resCat.ok) setCategorias(resCat.registros || []);
    } catch (err) {
      setError(MEITI.t('err_load_inventory', null, 'Error al cargar el inventario.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    if (soyAdmin) cargarDatos();
  }, [soyAdmin]);

  if (!soyAdmin) return <UI.Aviso tono="peligro" mensaje={MEITI.t('admin_only', null, 'Acceso denegado. Solo administradores.')} />;

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (!form.producto_id || !form.talle_id || !form.color_id) {
      return setError(MEITI.t('err_req_variant', null, 'Producto, talle y color son obligatorios.'));
    }

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? 'var_' + Date.now() : form.id,
      producto_id: form.producto_id,
      talle_id: form.talle_id,
      color_id: form.color_id,
      stock: Number(form.stock) || 0,
      sku: form.sku.trim()
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('msg_variant_saved', null, 'Variante guardada correctamente.'));
        setForm(vacio);
        setEditando(false);
        cargarDatos();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save_variant', null, 'Error al guardar la variante.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('q_delete_variant', null, '¿Borrar esta variante del inventario?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ur_variantes')}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: () => {
        setExito(MEITI.t('msg_variant_deleted', null, 'Variante eliminada.'));
        if (form.id === id) { setForm(vacio); setEditando(false); }
        cargarDatos();
      },
      alFallar: (err) => setError(err || MEITI.t('err_delete_variant', null, 'Error al eliminar.'))
    });
  };

  const abrirEdicion = (fila) => {
    setForm({
      id: fila.id,
      producto_id: fila.producto_id || '',
      talle_id: fila.talle_id || '',
      color_id: fila.color_id || '',
      stock: String(fila.stock || 0),
      sku: fila.sku || ''
    });
    setEditando(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const dataTabla = variantes.map(v => {
    const prod = productos.find(p => p.id === v.producto_id) || {};
    const talle = talles.find(t => t.id === v.talle_id) || {};
    const color = colores.find(c => c.id === v.color_id) || {};
    const cat = categorias.find(c => c.id === prod.categoria_id) || {};
    return {
      ...v,
      producto_nombre: prod.nombre || '---',
      categoria_nombre: cat.nombre || '---',
      talle_nombre: talle.nombre || '---',
      color_nombre: color.nombre || '---',
      color_hex: color.hex || '#ccc',
      imagen: prod.imagen_principal
    };
  });

  const filtrados = filtroProd 
    ? dataTabla.filter(v => v.producto_id === filtroProd)
    : dataTabla;

  const columnas = [
    { 
      clave: 'producto_nombre', 
      etiqueta: MEITI.t('col_product', null, 'Producto'), 
      render: f => (
        <div className="flex items-center gap-3">
          {f.imagen ? (
            <img src={f.imagen} alt={f.producto_nombre} className="w-8 h-8 rounded object-cover" />
          ) : (
            <div className="w-8 h-8 rounded bg-black/5 flex items-center justify-center"><Iconos.Package size={14} opacity={0.5} /></div>
          )}
          <div className="flex flex-col">
            <span className="font-bold">{f.producto_nombre}</span>
            <span className="text-xs opacity-60">{f.categoria_nombre}</span>
          </div>
        </div>
      )
    },
    { clave: 'sku', etiqueta: MEITI.t('col_sku', null, 'SKU'), render: f => <span className="font-mono text-xs opacity-80">{f.sku || '---'}</span> },
    { clave: 'talle_nombre', etiqueta: MEITI.t('col_size', null, 'Talle') },
    { 
      clave: 'color_nombre', 
      etiqueta: MEITI.t('col_color', null, 'Color'),
      render: f => (
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full border border-black/10" style={{ background: f.color_hex }}></div>
          <span>{f.color_nombre}</span>
        </div>
      )
    },
    { 
      clave: 'stock', 
      etiqueta: MEITI.t('col_stock', null, 'Stock'), 
      render: f => (
        <UI.Chip tono={Number(f.stock) === 0 ? 'peligro' : Number(f.stock) <= 5 ? 'alerta' : 'exito'}>
          {f.stock} unds
        </UI.Chip>
      )
    }
  ];

  return (
    <div className="flex flex-col gap-6">
      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
